            a: "[ਕਾਰਡ ਬਣਾਓ](/create) ਦਬਾਓ ਅਤੇ ਚੁਣੋ ਕਿ ਤੁਸੀਂ ਇਸ ਨੂੰ ਕਿਵੇਂ ਬਣਾਉਣਾ ਚਾਹੁੰਦੇ ਹੋ। **ਪਰਸਨਲ**: 6 ਛੋਟੇ ਸਵਾਲਾਂ ਦੇ ਜਵਾਬ ਦਿਓ ਅਤੇ ਅਸੀਂ ਤੁਹਾਡੇ ਜਵਾਬਾਂ ਮੁਤਾਬਕ ਪੂਰਾ ਕਾਰਡ ਨਵੇਂ ਸਿਰਿਓਂ ਬਣਾਉਂਦੇ ਹਾਂ। **ਰੈਡੀਮੇਡ ਡਿਜ਼ਾਈਨ**: ਸਾਡੇ {n} ਡਿਜ਼ਾਈਨਾਂ ਵਿੱਚੋਂ ਕੋਈ ਇੱਕ ਚੁਣੋ, ਉਨ੍ਹਾਂ ਹੀ ਸਵਾਲਾਂ ਦੇ ਜਵਾਬ ਦਿਓ, ਅਤੇ ਅਸੀਂ ਇਸ ਵਿੱਚ ਤੁਹਾਡੇ ਸ਼ਬਦ ਲਿਖ ਦਿੰਦੇ ਹਾਂ। ਦੋਹਾਂ ਤਰੀਕਿਆਂ ਵਿੱਚ, **ਕਾਰਟ ਵਿੱਚ ਪਾਓ** ਦਬਾਉਣ ਤੋਂ ਪਹਿਲਾਂ ਤੁਸੀਂ ਜੋ ਮਰਜ਼ੀ ਬਦਲ ਸਕਦੇ ਹੋ।",
