            a: "ਇੱਕ-ਇੱਕ ਸਕਰੀਨ ਕਰਕੇ ਦੱਸੋ, ਉਸੇ ਤਰਤੀਬ ਵਿੱਚ ਜਿਸ ਵਿੱਚ ਤੁਸੀਂ ਚਾਹੁੰਦੇ ਹੋ ਕਿ ਉਹ ਇਸ ਨੂੰ ਵੇਖਣ: \"ਜਦੋਂ ਇਹ ਖੁੱਲ੍ਹੇ, ਤਾਂ ਤਾਰਿਆਂ ਵਾਲਾ ਗੂੜ੍ਹਾ ਨੀਲਾ ਲਿਫ਼ਾਫ਼ਾ ਹੋਵੇ। ਫਿਰ ਇੱਕ ਸਵਾਲ ਜਿਸ ਵਿੱਚ ‘ਨਹੀਂ’ ਵਾਲਾ ਬਟਨ ਭੱਜ ਜਾਵੇ। ਫਿਰ ਇੱਕ ਗੇਮ ਜਿਸ ਵਿੱਚ ਉਹ ਦਿਲ ਫੜੇ। ਅਖ਼ੀਰ ਵਿੱਚ ਆਤਿਸ਼ਬਾਜ਼ੀ ਅਤੇ ਇੱਕ ਸੁਨੇਹਾ।\" ਰੰਗ ਅਤੇ ਅੰਦਾਜ਼ ਵੀ ਦੱਸੋ। ਅਸੀਂ ਇਸ ਨੂੰ ਬਿਲਕੁਲ ਉਸੇ ਤਰਤੀਬ ਵਿੱਚ ਬਣਾਉਂਦੇ ਹਾਂ, ਅਤੇ ਬਾਅਦ ਵਿੱਚ ਤੁਸੀਂ ਕੁਝ ਵੀ ਬਦਲ ਸਕਦੇ ਹੋ।",
